import os, subprocess, tarfile, json
import numpy as np
from PIL import Image
OUT = '/kaggle/working'
subprocess.run('pip install -q gdown', shell=True, check=True)
FILES = {'floodnet_r768.tar': ('1aTdx2Gi4OLSkNivpjwxHVsyCHSWmmPLK', 535408640),
          'rescuenet_r768.tar': ('1NAQKxhBDw46G7QjA5cRQcXCBB1dEN07s', 253265920),
          'generalist.ckpt': ('1_UrVMFy18kEcrxwD1b_ohxuTfJIsOWsG', 2967114775)}
for name, (fid, size) in FILES.items():
    p = f'{OUT}/{name}'
    subprocess.run(f'gdown --fuzzy -q https://drive.google.com/uc?id={fid} -O {p}', shell=True, check=True)
    got = os.path.getsize(p)
    print(name, got, 'OK' if got == size else f'SIZE MISMATCH (want {size})', flush=True)
    assert got == size

